args.code:
import json, re, os
from datetime import datetime

path = r'C:\AI\benchmark\v2\results-umay\sandboxes\umay-hizli__kapali\ajan-veri-temizle\siparisler.jsonl'
out_path = os.path.join(os.path.dirname(path), 'ozet.json')

def parse_tutar(t):
    if isinstance(t, bool):
        raise ValueError('boolean tutar')
    if isinstance(t, (int, float)):
        return float(t)
    if not isinstance(t, str):
        raise ValueError('tutar metin veya sayi degil')
    s = t.strip()
    s = s.replace('₺', '').replace('TL', '').replace('tl', '').strip()
    if '.' in s and ',' in s:
        s = s.replace('.', '').replace(',', '.')
    elif ',' in s:
        s = s.replace(',', '.')
    elif '.' in s:
        dot_after = s.split('.')[-1]
        if len(dot_after) == 3 and dot_after.isdigit():
            s = s.replace('.', '')
    return float(s)

def parse_tarih(t):
    if not isinstance(t, str):
        raise ValueError('tarih metin degil')
    s = t.strip()
    formats = ['%Y-%m-%d', '%Y/%m/%d', '%d.%m.%Y', '%d %B %Y']
    for fmt in formats:
        try:
            return datetime.strptime(s, fmt).date()
        except ValueError:
            pass
    raise ValueError('gecersiz tarih')

gecerli = {}
hatali = 0
bos = 0

with open(path, 'r', encoding='utf-8') as f:
    for line in f:
        satir = line.rstrip('\n')
        if satir.strip() == '':
            bos += 1
            continue
        try:
            obj = json.loads(satir)
        except Exception:
            hatali += 1
            continue
        if not isinstance(obj, dict):
            hatali += 1
            continue
        alanlar = {'id','musteri','tutar','tarih','durum'}
        if not alanlar.issubset(obj.keys()):
            hatali += 1
            continue
        try:
            tutar = parse_tutar(obj['tutar'])
            tarih = parse_tarih(obj['tarih'])
            durum = str(obj['durum']).strip().lower()
            musteri = str(obj['musteri']).strip()
            _ = obj['id']
        except Exception:
            hatali += 1
            continue
        gecerli[obj['id']] = {
            'id': obj['id'],
            'musteri': musteri,
            'tutar': tutar,
            'tarih': tarih,
            'durum': durum
        }

iptal_sayisi = sum(1 for v in gecerli.values() if v['durum'] == 'iptal')
aktif = {k: v for k, v in gecerli.items() if v['durum'] != 'iptal'}
toplam_tutar = round(sum(v['tutar'] for v in aktif.values()), 2)
aylik = {}
for v in aktif.values():
    anahtar = v['tarih'].strftime('%Y-%m')
    aylik[anahtar] = round(aylik.get(anahtar, 0.0) + v['tutar'], 2)
musteri_toplam = {}
for v in aktif.values():
    musteri_toplam[v['musteri']] = musteri_toplam.get(v['musteri'], 0.0) + v['tutar']
en_cok_harcayan = max(musteri_toplam, key=musteri_toplam.get) if musteri_toplam else None
sonuc = {
    'gecerli_kayit': len(gecerli),
    'hatali_satir': hatali,
    'iptal_sayisi': iptal_sayisi,
    'toplam_tutar': toplam_tutar,
    'aylik': aylik,
    'en_cok_harcayan': en_cok_harcayan
}
with open(out_path, 'w', encoding='utf-8') as f:
    json.dump(sonuc, f, ensure_ascii=False, indent=2)
print(json.dumps(sonuc, ensure_ascii=False, indent=2))

